// === Tab: mySketch ===
var mass = [];
var positionX = [];
var positionY = [];
var velocityX = [];
var velocityY = [];
var colors = [];

/////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  background(32);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
  background(32);
  generateParticles(120);
  updateParticles();
  drawParticles();
}

function drawParticles() {
  for (var particle = 0; particle < mass.length; particle++) {
    positionX[particle] += velocityX[particle];
    positionY[particle] += velocityY[particle];
    fill(colors[particle]);
    ellipse(positionX[particle], positionY[particle], mass[particle] * 1000, mass[particle] * 1000);
  }
}

function updateParticles() {
  for (var particleA = 0; particleA < mass.length; particleA++) {
    var accelerationX = 0, accelerationY = 0;

    for (var particleB = 0; particleB < mass.length; particleB++) {
      if (particleA != particleB) {
        var distanceX = positionX[particleB] - positionX[particleA];
        var distanceY = positionY[particleB] - positionY[particleA];

        var distance = sqrt(distanceX * distanceX + distanceY * distanceY);
        if (distance < 1) distance = 1;

        var force = (distance - 320) * mass[particleB] / distance;

        accelerationX += force * distanceX;
        accelerationY += force * distanceY;
      }
    }

    velocityX[particleA] = velocityX[particleA] * 0.02 + accelerationX * mass[particleA];
    velocityY[particleA] = velocityY[particleA] * 0.02 + accelerationY * mass[particleA];
  }
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function addNewParticle(x, y) {
  mass.push(random(0.004, 0.04));
  positionX.push(x);
  positionY.push(y);
  velocityX.push(0);
  velocityY.push(0);
  colors.push(randomColor());

  if (mass.length > 400) {
    var index = random(0, mass.length);
    mass.splice(index, 1);
    positionX.splice(index, 1);
    positionY.splice(index, 1);
    velocityX.splice(index, 1);
    velocityY.splice(index, 1);
    colors.splice(index, 1);
  }
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function randomColor() {
  return color(random(100, 255), noise(frameCount) * 255, noise(frameCount) * 255)
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function generateParticles(pNum) {
  translate(width/2, height/2);

  let index = frameCount % pNum;
  let dr = TWO_PI / pNum;
  let radians = dr * index + random(0, 6);

  let radius = (width / 100) * sin(frameCount % 100);


  addNewParticle(cos(radians) * radius, sin(radians) * radius); 
}

